<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Ubuntu-like Desktop</title>
<style>
  * { box-sizing: border-box; }
  html, body { margin: 0; padding: 0; height: 100%; overflow: hidden; font-family: "Segoe UI", "Ubuntu", system-ui, sans-serif; }

  #desktop {
    position: relative;
    width: 100vw;
    height: 100vh;
    overflow: hidden;
    background:
      radial-gradient(1200px 800px at 20% 20%, #3a2f6b 0%, transparent 60%),
      radial-gradient(1000px 700px at 80% 80%, #7a2f4f 0%, transparent 55%),
      linear-gradient(135deg, #1a1530 0%, #241a3d 50%, #101826 100%);
  }

  /* ---------- Taskbar ---------- */
  #taskbar {
    position: absolute; top: 0; left: 0; right: 0; height: 46px;
    display: flex; align-items: center; gap: 10px; padding: 0 12px;
    background: rgba(20, 18, 28, 0.82);
    backdrop-filter: blur(10px);
    border-bottom: 1px solid rgba(255,255,255,0.08);
    z-index: 1000;
  }
  #taskbar .brand { color: #eee; font-weight: 600; display:flex; align-items:center; gap:8px; }
  #taskbar .brand .logo { width:20px; height:20px; border-radius:50%; background: radial-gradient(circle at 30% 30%, #f4802b, #e95420); box-shadow: 0 0 8px rgba(233,84,32,.6); }
  .launchers { display:flex; gap:8px; }
  #open-files, #open-notepad {
    appearance: none; border: 1px solid rgba(255,255,255,0.12);
    background: rgba(255,255,255,0.06); color: #f2f2f2;
    padding: 7px 14px; border-radius: 8px; cursor: pointer;
    font-size: 13px; font-weight: 500; transition: all .15s ease;
  }
  #open-files:hover, #open-notepad:hover { background: rgba(255,255,255,0.14); border-color: rgba(255,255,255,0.25); }
  #open-files:active, #open-notepad:active { transform: translateY(1px); }
  #taskbar .spacer { flex: 1; }
  #clock { color: #e6e6e6; font-size: 13px; font-variant-numeric: tabular-nums; }

  /* ---------- Windows ---------- */
  .window {
    position: absolute; background: #2b2b2f;
    border-radius: 10px;
    box-shadow: 0 20px 60px rgba(0,0,0,.55), 0 0 0 1px rgba(255,255,255,0.06);
    display: flex; flex-direction: column; overflow: hidden;
    min-width: 360px; min-height: 240px;
  }
  .win-titlebar {
    height: 40px; flex: 0 0 40px; display: flex; align-items: center; gap: 10px;
    padding: 0 10px; background: linear-gradient(#35353a, #2b2b30); cursor: move; user-select: none;
    border-bottom: 1px solid rgba(0,0,0,.4);
  }
  .win-title { color: #eaeaea; font-size: 13px; font-weight: 600; }
  .win-close {
    margin-left: auto; width: 26px; height: 26px; border-radius: 6px;
    border: none; cursor: pointer; background: rgba(255,255,255,0.08); color: #ddd;
    font-size: 16px; line-height: 1; display:flex; align-items:center; justify-content:center;
    transition: background .15s ease;
  }
  .win-close:hover { background: #e95420; color: #fff; }
  .win-body { flex: 1; display: flex; flex-direction: column; min-height: 0; background:#1f1f22; }

  /* ---------- Files app ---------- */
  .files-toolbar {
    display:flex; align-items:center; gap:10px; padding: 8px 12px;
    background:#26262a; border-bottom:1px solid rgba(0,0,0,.4);
  }
  #files-up {
    border:1px solid rgba(255,255,255,0.12); background:rgba(255,255,255,0.06);
    color:#eee; padding:6px 12px; border-radius:7px; cursor:pointer; font-size:13px;
  }
  #files-up:hover { background: rgba(255,255,255,0.14); }
  #files-up:disabled { opacity:.4; cursor: default; }
  #files-path { color:#f2f2f2; font-size:13px; font-family: ui-monospace, "Cascadia Code", monospace; background: rgba(0,0,0,.25); padding:5px 10px; border-radius:6px; }
  .files-list { flex:1; overflow:auto; padding: 8px; display:flex; flex-direction:column; gap:4px; }
  .fs-item {
    display:flex; align-items:center; gap:10px; padding: 8px 12px; border-radius:7px;
    cursor: pointer; color:#eee; font-size:14px; user-select: none;
  }
  .fs-item:hover { background: rgba(255,255,255,0.08); }
  .fs-item.selected { background: rgba(233,84,32,0.25); outline: 1px solid rgba(233,84,32,.5); }
  .fs-item.folder::before { content:'\1F4C1'; }
  .fs-item.file::before { content:'\1F4C4'; opacity:.85; }

  /* ---------- Notepad app ---------- */
  .notepad-toolbar { display:flex; align-items:center; background:#26262a; border-bottom:1px solid rgba(0,0,0,.4); min-height: 40px; }
  .tabs { display:flex; align-items:center; gap:2px; flex:1; padding:5px 6px; overflow-x:auto; }
  .tab {
    padding: 7px 14px; border-radius: 7px 7px 0 0; cursor:pointer; font-size:13px; color:#cfcfcf;
    background: rgba(255,255,255,0.04); border:1px solid transparent; border-bottom:none;
    max-width:180px; overflow:hidden; text-overflow:ellipsis; white-space:nowrap;
  }
  .tab.active { background:#1f1f22; color:#fff; border-color: rgba(255,255,255,0.08); box-shadow: inset 0 2px 0 #e95420; }
  #new-tab { margin: 5px 6px; width:30px; height:30px; border-radius:6px; border:1px solid rgba(255,255,255,0.12); background:rgba(255,255,255,0.06); color:#eee; font-size:18px; cursor:pointer; line-height:1; }
  #new-tab:hover { background: rgba(255,255,255,0.14); }
  .editor { flex:1; width:100%; min-height:0; resize:none; border:none; outline:none; background:#1a1a1d; color:#e8e8e8; padding:14px 16px; font-size:14px; line-height:1.5; font-family: ui-monospace, "Cascadia Code", "Consolas", monospace; }

  /* ---------- Desktop icons (polish) ---------- */
  .desktop-icon { position:absolute; width:88px; text-align:center; color:#fff; cursor:pointer; padding:8px; border-radius:8px; user-select:none; }
  .desktop-icon:hover { background: rgba(255,255,255,0.14); }
  .desktop-icon .ico { font-size:40px; display:block; filter: drop-shadow(0 3px 5px rgba(0,0,0,.5)); }
  .desktop-icon .lbl { font-size:12px; margin-top:3px; text-shadow:0 1px 2px rgba(0,0,0,.8); }
</style>
</head>
<body>
<div id="desktop">
  <div id="taskbar">
    <div class="brand"><span class="logo"></span><span>Ubuntu Desktop</span></div>
    <div class="launchers">
      <button id="open-files">📁 Files</button>
      <button id="open-notepad">📝 Notepad</button>
    </div>
    <div class="spacer"></div>
    <div id="clock">--:--</div>
  </div>

  <!-- Files window -->
  <div id="files-window" class="window" style="display:none;">
    <div class="win-titlebar">
      <span class="win-title">Files</span>
      <button class="win-close">×</button>
    </div>
    <div class="win-body">
      <div class="files-toolbar">
        <button id="files-up">↑ Up</button>
        <span id="files-path">/</span>
      </div>
      <div id="files-list" class="files-list"></div>
    </div>
  </div>

  <!-- Notepad window -->
  <div id="notepad-window" class="window" style="display:none;">
    <div class="win-titlebar">
      <span class="win-title">Notepad</span>
      <button class="win-close">×</button>
    </div>
    <div class="win-body">
      <div class="notepad-toolbar">
        <div id="tabs" class="tabs"></div>
        <button id="new-tab">+</button>
      </div>
      <textarea id="editor" class="editor"></textarea>
    </div>
  </div>
</div>

<script>
(function(){
  'use strict';

  /* ================= Filesystem (static fake data) ================= */
  const fsData = {
    '/': ['bin', 'etc', 'home', 'usr', 'var'],
    '/bin': ['bash', 'ls', 'cp', 'mv', 'mkdir'],
    '/etc': ['passwd', 'hostname', 'fstab', 'ssh'],
    '/home': ['user'],
    '/usr': ['bin', 'lib', 'share', 'include'],
    '/var': ['log', 'tmp', 'cache'],
    '/home/user': ['Documents', 'Downloads', 'Pictures', 'notes.txt', '.bashrc'],
    '/home/user/Documents': ['report.md', 'todo.txt', 'resume.pdf'],
    '/home/user/Downloads': ['image.png', 'archive.zip'],
    '/home/user/Pictures': ['wallpaper.jpg', 'vacation'],
    '/home/user/Pictures/vacation': ['beach.jpg', 'mountain.jpg'],
    '/var/log': ['syslog', 'auth.log'],
    '/usr/share': ['fonts', 'man']
  };

  const isDir = (p) => Object.prototype.hasOwnProperty.call(fsData, p);
  const childrenOf = (p) => fsData[p] || [];

  /* ================= Window management ================= */
  const desktop = document.getElementById('desktop');
  let zCounter = 10;

  function bringToFront(win){ win.style.zIndex = ++zCounter; }

  function openWindow(id){
    const win = document.getElementById(id);
    win.style.display = 'flex';
    bringToFront(win);
    if (id === 'notepad-window') editor.focus();
  }

  document.querySelectorAll('.win-close').forEach(btn => {
    btn.addEventListener('click', (e) => {
      const win = e.target.closest('.window');
      if (win) win.style.display = 'none';
    });
  });

  document.querySelectorAll('.window').forEach(win => {
    win.addEventListener('mousedown', () => bringToFront(win));
    makeDraggable(win);
  });

  function makeDraggable(win){
    const titlebar = win.querySelector('.win-titlebar');
    let dragging = false, sx=0, sy=0, ox=0, oy=0;
    titlebar.addEventListener('mousedown', (e) => {
      if (e.target.classList.contains('win-close')) return;
      dragging = true;
      sx = e.clientX; sy = e.clientY;
      ox = win.offsetLeft; oy = win.offsetTop;
      bringToFront(win);
      document.addEventListener('mousemove', onMove);
      document.addEventListener('mouseup', onUp);
      e.preventDefault();
    });
    function onMove(e){
      if (!dragging) return;
      const nl = ox + (e.clientX - sx);
      const nt = oy + (e.clientY - sy);
      const maxL = Math.max(0, window.innerWidth - 80);
      const maxT = Math.max(0, window.innerHeight - 50);
      win.style.left = Math.min(maxL, Math.max(0, nl)) + 'px';
      win.style.top  = Math.min(maxT, Math.max(0, nt)) + 'px';
    }
    function onUp(){
      dragging = false;
      document.removeEventListener('mousemove', onMove);
      document.removeEventListener('mouseup', onUp);
    }
  }

  document.getElementById('open-files').addEventListener('click', () => {
    openWindow('files-window');
    const fw = document.getElementById('files-window');
    fw.style.left = '120px'; fw.style.top = '90px';
    fw.style.width = '720px'; fw.style.height = '480px';
  });
  document.getElementById('open-notepad').addEventListener('click', () => {
    openWindow('notepad-window');
    const nw = document.getElementById('notepad-window');
    nw.style.left = '300px'; nw.style.top = '140px';
    nw.style.width = '640px'; nw.style.height = '480px';
  });

  /* ================= Files app ================= */
  let currentPath = '/';
  const filesPath = document.getElementById('files-path');
  const filesList = document.getElementById('files-list');
  const filesUp   = document.getElementById('files-up');

  function renderFiles(path){
    currentPath = path;
    filesPath.textContent = path;
    filesUp.disabled = (path === '/');
    filesList.innerHTML = '';
    const entries = childrenOf(path).slice().sort((a,b) => a.localeCompare(b));
    for (const name of entries){
      const item = document.createElement('div');
      item.className = 'fs-item';
      item.textContent = name;
      const full = path === '/' ? '/' + name : path + '/' + name;
      if (isDir(full)){
        item.classList.add('folder');
        item.addEventListener('dblclick', () => renderFiles(full));
      } else {
        item.classList.add('file');
      }
      filesList.appendChild(item);
    }
  }

  filesUp.addEventListener('click', () => {
    if (currentPath === '/') return;
    const idx = currentPath.lastIndexOf('/');
    renderFiles(idx === 0 ? '/' : currentPath.slice(0, idx));
  });

  /* ================= Notepad app ================= */
  const TABS_KEY = 'ubuntu-notepad-tabs';
  let tabs = [];
  let activeId = null;
  let seq = 0;

  const tabsEl   = document.getElementById('tabs');
  const editor   = document.getElementById('editor');
  const newTabBtn= document.getElementById('new-tab');

  function initSeq(){
    let m = 0;
    for (const t of tabs){
      const n = parseInt(String(t.id).replace(/\D/g,''), 10);
      if (!isNaN(n) && n > m) m = n;
    }
    seq = m;
  }

  function loadState(){
    try {
      const raw = localStorage.getItem(TABS_KEY);
      if (raw){
        const state = JSON.parse(raw);
        if (Array.isArray(state.tabs) && state.tabs.length){
          tabs = state.tabs;
          activeId = state.activeId || tabs[0].id;
        }
      }
    } catch(e){}
    initSeq();
    if (!tabs.length) createTab();
    renderTabs();
  }

  function saveState(){
    try { localStorage.setItem(TABS_KEY, JSON.stringify({ tabs, activeId })); } catch(e){}
  }

  function createTab(name, content){
    const id = 't' + (++seq);
    const t = { id, name: name || ('Untitled ' + (tabs.length + 1)), content: content != null ? content : '' };
    tabs.push(t);
    return t;
  }

  function getActiveTab(){ return tabs.find(t => t.id === activeId) || tabs[0]; }

  function renderTabs(){
    tabsEl.innerHTML = '';
    for (const t of tabs){
      const el = document.createElement('div');
      el.className = 'tab';
      if (t.id === activeId) el.classList.add('active');
      el.textContent = t.name;
      el.addEventListener('click', () => switchTab(t.id));
      tabsEl.appendChild(el);
    }
    syncEditor();
  }

  function switchTab(id){
    activeId = id;
    renderTabs();
  }

  // Keep the textarea in sync when switching tabs, without clobbering live typing.
  function syncEditor(){
    const t = getActiveTab();
    if (editor.value === t.content) return;
    editor.value = t.content;
  }

  newTabBtn.addEventListener('click', () => {
    const t = createTab();
    activeId = t.id;
    renderTabs();
    saveState();
    editor.focus();
  });

  editor.addEventListener('input', () => {
    const t = getActiveTab();
    if (t){ t.content = editor.value; saveState(); }
  });

  /* ================= Desktop icon (polish) ================= */
  const homeIcon = document.createElement('div');
  homeIcon.className = 'desktop-icon';
  homeIcon.style.left = '28px';
  homeIcon.style.top  = '76px';
  homeIcon.innerHTML = '<span class="ico">📁</span><span class="lbl">Home</span>';
  homeIcon.addEventListener('dblclick', () => {
    openWindow('files-window');
    const fw = document.getElementById('files-window');
    fw.style.left = '120px'; fw.style.top = '90px';
    fw.style.width = '720px'; fw.style.height = '480px';
    renderFiles('/home/user');
  });
  desktop.appendChild(homeIcon);

  /* ================= Clock ================= */
  const clock = document.getElementById('clock');
  function tick(){ clock.textContent = new Date().toLocaleTimeString([], { hour:'2-digit', minute:'2-digit' }); }
  tick(); setInterval(tick, 1000);

  /* ================= Init ================= */
  renderFiles('/');
  loadState();
})();
</script>
</body>
</html>
